		shroud_l2.xRot += Mth.sin(state.ageInTicks * 0.13999999999999999F + 1.8F) * (0.18F + 0.15F * state.walkAnimationSpeed);
		shroud_r0.xRot += Mth.sin(state.ageInTicks * 0.12F + 1.5F) * (0.12F + 0.15F * state.walkAnimationSpeed);
